import json

def parse(value):
    return json.loads(value) if isinstance(value,str) else value

def unpack(value):
    value = parse(value)
    return value.get('structuredOutputs', value)

def host(value):
    return str(value).lower().split('://')[-1].split('/')[0].removeprefix('www.')

def ordinal(date):
    y,m,d = [int(p) for p in str(date)[:10].split('-')]
    leap = y%4==0 and (y%100!=0 or y%400==0)
    lengths=[31,29 if leap else 28,31,30,31,30,31,31,30,31,30,31]
    if y<1 or not 1<=m<=12 or not 1<=d<=lengths[m-1]: raise ValueError('Invalid date')
    return 365*(y-1)+(y-1)//4-(y-1)//100+(y-1)//400+sum(lengths[:m-1])+d

def handler(context):
    contract=parse(context.get_input('contract_json'))
    receipts=parse(context.get_input('evidence_json'))
    research=unpack(context.get_input('research_json'))
    audit=unpack(context.get_input('audit_json'))
    holds=list(contract.get('missing_inputs',[])); mode=research.get('mode'); settings=contract['settings']
    gates=['identity_verified','current_claim_verified','temporal_claim_supported','offer_relevant',
           'buyer_relevant','inference_bounded','meaningful_observation']
    if contract.get('icp'): gates.append('icp_fit_verified')
    for key in gates:
        if audit.get(key) is not True: holds.append('Audit gate: '+key)
    if audit.get('contradiction') is not False: holds.append('Contradiction or unresolved audit state')
    if mode not in ['historical_change','dated_event','current_condition']:
        holds.append('No supported observation mode')
    if settings['require_shift'] and mode=='current_condition': holds.append('A shift is required; current condition alone is insufficient')
    if not str(research.get('current_url','')).startswith('https://') or not research.get('current_excerpt'):
        holds.append('Missing current source URL or excerpt')
    comparison={}
    if contract.get('comparison',{}).get('mode')=='before_after' and mode!='historical_change':
        holds.append('Before/after mode requires a supported historical comparison; no event fallback')
    if mode=='historical_change':
        matches=[r for r in receipts if r['id']==research.get('history_receipt_id')]
        current_matches=[r for r in receipts if r['id']==research.get('current_receipt_id')]
        current=current_matches[0] if len(current_matches)==1 else None
        now_date=research.get('current_observed_at')
        if research.get('current_receipt_id') and current is None:
            holds.append('Unknown current receipt ID')
        if current:
            now_date=current.get('captured_at') or current.get('observed_at')
            if current.get('role')=='past' or current.get('requested_as_of'):
                holds.append('A historical Snapshot cannot stand in for current observation')
            quote=str(research.get('current_excerpt','')).strip()
            if len(quote)<15 or quote not in current.get('text',''):
                holds.append('Current quotation not present verbatim in receipt text')
            if current['url'].rstrip('/')!=str(research.get('current_url','')).rstrip('/'):
                holds.append('Current receipt URL does not match cited current source')
            if host(current['url'])!=contract['company_domain']:
                holds.append('Current receipt entity mismatch')
        try:
            current_day=ordinal(now_date)
            age=ordinal(contract['today'])-current_day
            if age<0 or age>settings.get('max_current_age_days',7): holds.append('Current observation is future or stale')
        except (ValueError,TypeError):
            current_day=None;holds.append('Current observation needs a valid observation date')
        if len(matches)!=1:
            holds.append('Historical change requires an exact supplied receipt')
        else:
            receipt=matches[0];quote=str(research.get('before_excerpt','')).strip()
            if len(quote)<15 or quote not in receipt.get('text','') or len(receipt.get('text','').strip())<30:
                holds.append('Historical quotation requires substantive verbatim receipt text; title-only history is insufficient')
            if host(receipt['url'])!=contract['company_domain'] or receipt.get('role')=='current':
                holds.append('Historical receipt entity or role mismatch')
            cutoff=receipt.get('requested_as_of')
            past_date=receipt.get('captured_at') or cutoff or receipt.get('observed_at')
            try:
                past_day=ordinal(past_date)
                # An as-of cutoff is a bound, never the actual capture or change date.
                bound=ordinal(cutoff) if cutoff else past_day
                if past_day>bound: holds.append('Historical capture follows requested cutoff')
                if current_day is not None and bound>=current_day: holds.append('Past cutoff must precede current observation')
                if bound>ordinal(contract['today']): holds.append('Future historical cutoff')
            except (ValueError,TypeError): holds.append('Invalid historical cutoff or capture date')
            selected=contract.get('comparison',{}).get('as_of')
            if selected and str(cutoff or '')[:10]!=selected:
                holds.append('Historical receipt does not match the selected comparison cutoff')
            if current and ' '.join(receipt.get('text','').lower().split())==' '.join(current.get('text','').lower().split()):
                holds.append('Past and current content is unchanged')
            comparison={'past_receipt_id':receipt['id'],'current_receipt_id':current['id'] if current else '',
                        'past_url':receipt['url'],'current_url':research.get('current_url'),
                        'requested_as_of':cutoff,'past_captured_at':receipt.get('captured_at'),
                        'current_observed_at':now_date,'before_claim':research.get('before_claim'),
                        'after_claim':research.get('after_claim'),'change_kind':research.get('change_kind'),
                        'date_rule':'Cutoff is not capture or change date. Undated history uses earlier/now, never an invented month.'}
        for key in ['historical_claim_verified','material_shift','comparable_observations','before_after_distinct']:
            if audit.get(key) is not True: holds.append('Historical comparison gate: '+key)
        if not research.get('before_claim') or not research.get('after_claim'):
            holds.append('Comparison requires both past and current claims')
        if research.get('change_kind') not in ['positioning','offering','audience','pricing','hiring','other']:
            holds.append('Comparison needs a supported change kind')
    if mode=='dated_event':
        try:
            date=str(research.get('event_date') or '')
            if len(date)==7: date+='-01'  # Oldest possible day gives conservative freshness.
            elif len(date)!=10: raise ValueError('Use source-supported YYYY-MM or YYYY-MM-DD')
            age=ordinal(contract['today'])-ordinal(date)
            if age<0 or age>settings['max_event_age_days']: holds.append('Event date is future or stale')
        except (ValueError,TypeError): holds.append('Dated event requires a valid event date')
        if audit.get('material_shift') is not True: holds.append('No material change established')
    if research.get('selected_capability') not in contract['sender']['capabilities']:
        holds.append('Offer bridge must select an exact supplied capability')
    weights={'evidence':.30,'commercial':.25,'offer_fit':.20,'timing':.15,'specificity':.10}
    components={}; product=1.0
    for key,weight in weights.items():
        value=audit.get(key+'_strength')
        if type(value) is not int or not 0<=value<=4:
            holds.append('Invalid audit strength: '+key); value=0
        components[key]=value*25
        product*=max(.01,value/4)**weight
        if value<2: holds.append('Insufficient '+key)
    score=round(100*product,1) if any(components.values()) else 0
    if score<settings['minimum_alpha_score']: holds.append('Alpha score below '+str(settings['minimum_alpha_score']))
    card={'contract':contract,'research':research,'audit':audit,'evidence_receipts':receipts,
          'comparison':comparison,'alpha_score':score,'components':components,'hold_reasons':holds,
          'state':'EVIDENCE_READY' if not holds else 'RESEARCH_REQUIRED',
          'claim_boundary':'A public positioning change supports a relevance hypothesis, not proof of operational change, budget, pain, intent or outcome.',
          'score_note':'Heuristic strengths from a separate deeplineagent audit; not conversion probabilities.'}
    return {'eligible':not holds,'alpha_card_json':json.dumps(card),'alpha_score':score,
            'hold_reasons':holds,'state':card['state']}

spec.agentPrompt:
Repair the draft using only the evidence card and the critic's specific objections. Do not browse, invent facts, or weaken the criticism.
CARD: {{alpha_card_json}}
DRAFT: {{draft_json}}
CRITIQUE: {{review_json}}
Return subject, observation, implication and cta only. Code inserts contract.sender.offer verbatim between implication and cta. Do not output an offer field or rewrite that fixed offer. Do not add services to the generated implication. If every required review gate is true and works_without_signal=false, return all original draft fields exactly. Otherwise fix the stated problems while preserving supported observations and the actual offer. Remove unsupported result/comparative adjectives such as cleaner, better, faster or improved. State concrete implementation work, not unproven outcomes. Make the observation and implication specific enough to earn the fixed actual offer without adding promises or services. Keep business implications tentative. No fabricated familiarity, private pain, assets, dates or outcomes. Aim 55-85 words before the provided signature; obey contract.settings.max_words for the assembled email. No greeting or signature in your fields. If contract.writing.cta is nonempty, copy it EXACTLY. Otherwise use one small relevant question. Plain punctuation only. If a critique cannot be resolved from available evidence, do not invent missing proof; the final reviewer will hold it.
EXPLICIT COMPARISON: For historical_change, the observation line MUST contain both the earlier fact and the current fact in one natural contrast: Earlier X; now Y, or You have shifted the emphasis from X toward Y. Use research.before_claim and after_claim, respecting change_kind. Merely stating the current condition fails. Use precise history dates only if an actual capture date supports them; requested_as_of is not a date you may attribute to the company's messaging. With unknown capture date, use earlier/now or from/toward. Do not imply longitudinal monitoring, discontinued services, launches, changed prices or operations unless both evidence and audit support those exact claims. Preserve both sides during revision.

