import json, re

def unpack(value):
    value=json.loads(value) if isinstance(value,str) else value
    return value.get('structuredOutputs',value)

def handler(context):
    card=unpack(context.get_input('alpha_card_json'))
    draft=unpack(context.get_input('draft_json'))
    review=unpack(context.get_input('review_json'))
    holds=[]; c=card['contract']; writing=c.get('writing',{})
    if card.get('state')!='EVIDENCE_READY': holds.append('Evidence is not ready')
    keys=['subject','observation','implication','cta']
    for key in keys:
        if not isinstance(draft.get(key),str) or not draft[key].strip(): holds.append('Missing '+key)
    lines=[str(draft.get('observation','')).strip(),str(draft.get('implication','')).strip(),c['sender']['offer'],str(draft.get('cta','')).strip()]
    if not c['sender']['offer'].strip(): holds.append('Missing actual offer')
    if writing.get('cta') and lines[-1]!=writing['cta']: holds.append("CTA differs from the user's exact wording")
    greeting=writing.get('greeting','')
    signature=writing.get('signature',c['sender']['sender_name'])
    body='\n\n'.join(([greeting] if greeting else [])+lines+([signature] if signature else []))
    generated=[str(draft.get('subject','')),lines[0],lines[1]]+([] if writing.get('cta') else [lines[-1]])
    text='\n'.join(generated); lower=text.lower()
    if '{{' in body or '}}' in body: holds.append('Unresolved placeholder')
    if len(body.split())>c['settings']['max_words']: holds.append('Body exceeds word limit')
    if len(str(draft.get('subject','')).split())>7: holds.append('Subject exceeds seven words')
    if '—' in text or '–' in text: holds.append('Use plain punctuation')
    for phrase in ['your website','your homepage','been watching','been following','we noticed over','tracked your','guarantee','congratulations','congrats']:
        if phrase in lower: holds.append('Research mechanics or unsupported familiarity: '+phrase)
    if re.search(r'\b(exa|deepline|deeplineagent|snapshot)\b',lower): holds.append('Research provider named in copy')
    if re.search(r'https?://|\{\{|\}\}|\[[^\]]*\]|\b\d+(?:\.\d+)?%',text):
        holds.append('Unreviewed URL, placeholder or numeric outcome claim')
    if not writing.get('cta') and (lines[-1].count('?')!=1 or text.count('?')!=1): holds.append('Use one small question as the CTA')
    if not any(w in lines[1].lower() for w in ['may','might','could','if ','can ','often ','does ','whether']):
        holds.append('Business implication must remain bounded')
    review_gates=['all_claims_supported','shift_visible','offer_faithful','subject_faithful',
                  'no_fabricated_familiarity','no_unearned_outcomes','buyer_relevant','specific_not_generic']
    if card.get('research',{}).get('mode')=='historical_change':
        review_gates += ['past_and_current_explicit','date_precision_faithful']
    for key in review_gates:
        if review.get(key) is not True: holds.append('Copy review: '+key)
    if review.get('works_without_signal') is not False:
        holds.append('Copy still works unchanged without the signal')
    state='DRAFT_READY_FOR_REVIEW' if not holds else 'COPY_REVIEW_REQUIRED'
    return {'isTerminal':True,'state':state,'subject':draft.get('subject',''),'body':body,
            'alpha_score':card['alpha_score'],'hold_reasons':holds,
            'source_id':c.get('source_id',''),'batch_id':c.get('batch_id',''),'comparison_json':json.dumps(card.get('comparison',{})),
            'source_record_id':c.get('source_record_id',''),'source_kind':c.get('source_kind','manual'),
            'alpha_card_json':json.dumps(card),'copy_review_json':json.dumps(review),
            'word_count':len(body.split()),'sent':False,
            'next_step':'Review the source-backed draft. No sending or enrollment is connected.'}

import json

def handler(context):
    value=context.get_input('alpha_card_json')
    card=json.loads(value) if isinstance(value,str) else value
    return {'isTerminal':True,'state':'RESEARCH_REQUIRED','subject':'','body':'','sent':False,
